        mc("lo17","1","Was ist ein transparentes (durchsichtiges) Objekt? 🔍","What is a transparent object?","Qu'est-ce qu'un objet transparent ?","Che cos'è un oggetto trasparente?","Eines, durch das Licht hindurchgeht",["Eines, das Licht reflektiert","Eines, durch das Licht hindurchgeht","Eines, das Schatten wirft","Eines, das Licht absorbiert"],"Fensterglas = transparent.","Transparent = Licht geht durch."),
        fib("lo18","1","Der Mond leuchtet, weil er ___ von der Sonne reflektiert. 🌕","The moon shines because it ___ sunlight.","La lune brille parce qu'elle ___ la lumière du soleil.","La luna brilla perché ___ la luce del sole.","Licht","Mond = Reflektor, keine eigene Lichtquelle.","Sonnenlicht → Mond → Erde."),
        mc("lo19","1","Wie schnell bewegt sich Licht ungefähr? 🚀","How fast does light travel approximately?","À quelle vitesse la lumière se déplace-t-elle environ ?","Con quale velocità viaggia la luce circa?","300'000 km/s",["3'000 km/s","30'000 km/s","300'000 km/s","3'000'000 km/s"],"Licht ist das Schnellste im Universum.","c = 300'000 km/s."),
        fib("lo20","1","Ein ___ Material lässt kein Licht hindurch (z.B. Holz, Metall).","An ___ material lets no light through (e.g. wood, metal).","Un matériau ___ ne laisse pas passer la lumière (ex. bois, métal).","Un materiale ___ non lascia passare la luce (es. legno, metallo).","undurchsichtiges (opakes)","Holz = undurchsichtig.","Kein Licht hindurch = opak."),
        fib("lo21","1","Wenn Licht auf einen Spiegel trifft, wird es im gleichen ___ zurückgeworfen.","When light hits a mirror, it is reflected at the same ___.","Quand la lumière frappe un miroir, elle est réfléchie au même ___.","Quando la luce colpisce uno specchio, viene riflessa allo stesso ___.","Winkel","Einfallswinkel = Ausfallswinkel.","Reflexionsgesetz."),
        mc("lo22","2","Was ist Refraktion (Brechung) von Licht? 💧","What is light refraction?","Qu'est-ce que la réfraction de la lumière ?","Che cos'è la rifrazione della luce?","Licht ändert seine Richtung beim Übergang zwischen Medien",["Licht wird absorbiert","Licht ändert seine Richtung beim Übergang zwischen Medien","Licht prallt zurück","Licht wird dunkler"],"Strohhalm im Wasser sieht gebogen aus.","Luft → Wasser = Richtungsänderung."),
        fib("lo23","2","Ein Prisma zerlegt weisses Licht in seine ___. 🌈","A prism splits white light into its ___.","Un prisme décompose la lumière blanche en ses ___.","Un prisma scompone la luce bianca nei suoi ___.","Farben (Spektrum)","Newton entdeckte Licht-Zerlegung.","Prisma → Regenbogenspektrum."),
