# ─── LICHT-OPTIK GRADE 4 (lo11b–lo50b) ──────────────────────────────────────
def lo_g4():
    # Very similar to grade 3 but ids have 'b' suffix
    g3 = lo_g3()
    result = []
    for line in g3:
        # Replace the exercise ID
        import re
        line = re.sub(r'id: "lo(\d+)"', lambda m: f'id: "lo{m.group(1)}b"', line)
        result.append(line)
    return result

